journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c05_started }
	OR = {
		AND = { c:NMG ?= this OR = { ywc_c05_case_ready_nmg = yes var:ywc_c05_case_open ?= 1 } }
		AND = { c:MEX ?= this var:ywc_c05_case_open ?= 1 }
		AND = { OR = { c:USA ?= this c:SHU ?= this c:JHG ?= this c:NQG ?= this } var:ywc_c05_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c05_started }
	OR = {
		AND = { c:NMG ?= this ywc_c05_case_ready_nmg = yes }
		AND = { c:MEX ?= this var:ywc_c05_case_open ?= 1 }
		AND = { OR = { c:USA ?= this c:SHU ?= this c:JHG ?= this c:NQG ?= this } var:ywc_c05_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c05_started } }
		set_variable = { name = ywc_c05_started value = 1 }
		set_variable = { name = ywc_c05_popup_epoch value = 0 }
		set_variable = { name = ywc_c05_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c05_popup_epoch } } set_variable = { name = ywc_c05_popup_epoch value = 0 } }
	if = { limit = { c:NMG ?= this NOT = { has_variable = ywc_c05_role } } set_variable = { name = ywc_c05_role value = 1 } }
	if = { limit = { c:MEX ?= this NOT = { has_variable = ywc_c05_role } } set_variable = { name = ywc_c05_role value = 2 } }
	if = { limit = { OR = { c:USA ?= this c:SHU ?= this c:JHG ?= this c:NQG ?= this } NOT = { has_variable = ywc_c05_role } } set_variable = { name = ywc_c05_role value = 3 } }
	if = { limit = { c:NMG ?= this NOT = { has_variable = ywc_c05_stage } }
		set_variable = { name = ywc_c05_case_open value = 1 }
		set_variable = { name = ywc_c05_stage value = 1400 }
		set_variable = { name = ywc_c05_pending value = 1400 }
	}
}
on_monthly_pulse = {
	effect = {
		if = { limit = { c:NMG ?= this var:ywc_c05_stage ?= 1413 }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { OR = { ywc_c05_responses_resolved = yes var:ywc_c05_wait_age >= 12 } } ywc_c05_init_after_responses = yes }
		}
		if = { limit = {
				OR = { c:MEX ?= this OR = { c:USA ?= this c:SHU ?= this c:JHG ?= this c:NQG ?= this } }
				OR = { var:ywc_c05_stage ?= 1402 var:ywc_c05_stage ?= 1403 }
				ywc_c05_initiator_gone = yes
			}
			ywc_c05_close_no_talks = yes
		}
		if = { limit = { ywc_c05_nmg_delivery_1400 = yes } trigger_event = { id = ywc_crisis.1400 } }
		if = { limit = { ywc_c05_nmg_delivery_1401 = yes } trigger_event = { id = ywc_crisis.1401 } }
		if = { limit = { ywc_c05_mex_delivery_1402 = yes } trigger_event = { id = ywc_crisis.1402 } }
		if = { limit = { ywc_c05_usa_delivery_1403 = yes } trigger_event = { id = ywc_crisis.1403 } }
		if = { limit = { ywc_c05_shu_delivery_1403 = yes } trigger_event = { id = ywc_crisis.1403 } }
		if = { limit = { ywc_c05_jhg_delivery_1403 = yes } trigger_event = { id = ywc_crisis.1403 } }
		if = { limit = { ywc_c05_nqg_delivery_1403 = yes } trigger_event = { id = ywc_crisis.1403 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c05_budget_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c05_started
	var:ywc_c05_budget_open ?= 1
	OR = { c:NMG ?= this c:MEX ?= this }
	NOT = { has_variable = ywc_c05_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c05_popup_epoch } } set_variable = { name = ywc_c05_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { c:MEX ?= this var:ywc_c05_stage ?= 1405 NOT = { ywc_c05_initiator_alive_for_me = yes } }
			ywc_c05_close_no_talks = yes
		}
		if = { limit = { ywc_c05_nmg_delivery_1404 = yes } trigger_event = { id = ywc_crisis.1404 } }
		if = { limit = { ywc_c05_mex_delivery_1405 = yes } trigger_event = { id = ywc_crisis.1405 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c05_review_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c05_started
	var:ywc_c05_review_open ?= 1
	OR = { c:NMG ?= this c:MEX ?= this }
	NOT = { has_variable = ywc_c05_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c05_popup_epoch } } set_variable = { name = ywc_c05_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { c:NMG ?= this var:ywc_c05_stage ?= 1417 }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { OR = { ywc_c05_mex_remit_recorded = yes ywc_c05_initiator_gone = yes var:ywc_c05_wait_age >= 12 } }
				set_variable = { name = ywc_c05_stage value = 1408 }
				set_variable = { name = ywc_c05_pending value = 1408 }
				set_variable = { name = ywc_c05_wait_age value = 0 }
				change_variable = { name = ywc_c05_popup_epoch add = 1 }
			}
		}
		if = { limit = { c:NMG ?= this var:ywc_c05_stage ?= 1420 }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { OR = { ywc_c05_mex_draft_recorded = yes ywc_c05_initiator_gone = yes var:ywc_c05_wait_age >= 24 } }
				set_variable = { name = ywc_c05_stage value = 1415 }
				set_variable = { name = ywc_c05_pending value = 1415 }
				set_variable = { name = ywc_c05_wait_age value = 0 }
				change_variable = { name = ywc_c05_popup_epoch add = 1 }
			}
		}
		if = { limit = { c:NMG ?= this var:ywc_c05_stage ?= 1415 NOT = { has_variable = ywc_c05_outcome } }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { OR = { AND = { var:ywc_c05_wait_age >= 24 ywc_c05_mex_cannot_ratify = yes } var:ywc_c05_wait_age >= 36 } }
				ywc_c05_settle_limited = yes
			}
		}
		if = { limit = { c:NMG ?= this var:ywc_c05_stage ?= 1412 }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { var:ywc_c05_wait_age >= 12 } ywc_c05_aftermath_kept = yes }
		}
		if = { limit = { c:MEX ?= this var:ywc_c05_stage ?= 1418 }
			change_variable = { name = ywc_c05_wait_age add = 1 }
			if = { limit = { OR = {
					ywc_c05_initiator_gone = yes
					var:ywc_c05_wait_age >= 24
					c:NMG ?= { is_country_alive = yes has_variable = ywc_c05_outcome }
				} }
				set_variable = { name = ywc_c05_review_open value = 1 }
				set_variable = { name = ywc_c05_stage value = 1409 }
				set_variable = { name = ywc_c05_pending value = 1409 }
				set_variable = { name = ywc_c05_wait_age value = 0 }
				change_variable = { name = ywc_c05_popup_epoch add = 1 }
			}
		}
		if = { limit = { c:MEX ?= this OR = { var:ywc_c05_stage ?= 1414 var:ywc_c05_stage ?= 1409 var:ywc_c05_stage ?= 1416 } ywc_c05_initiator_gone = yes }
			ywc_c05_close_no_talks = yes
		}
		if = { limit = {
				c:MEX ?= this
				has_variable = ywc_c05_mex_confirm
				NOT = { has_variable = ywc_c05_outcome }
				c:NMG ?= { is_country_alive = yes OR = { var:ywc_c05_outcome ?= 1 var:ywc_c05_outcome ?= 2 var:ywc_c05_outcome ?= 3 } }
			}
			ywc_c05_mex_mirror_settle = yes
		}
		if = { limit = { ywc_c05_nmg_delivery_1406 = yes } trigger_event = { id = ywc_crisis.1406 } }
		if = { limit = { ywc_c05_nmg_delivery_1407 = yes } trigger_event = { id = ywc_crisis.1407 } }
		if = { limit = { ywc_c05_mex_delivery_1414 = yes } trigger_event = { id = ywc_crisis.1407 } }
		if = { limit = { ywc_c05_nmg_delivery_1408 = yes } trigger_event = { id = ywc_crisis.1408 } }
		if = { limit = { ywc_c05_mex_delivery_1409 = yes } trigger_event = { id = ywc_crisis.1409 } }
		if = { limit = { ywc_c05_nmg_delivery_1415 = yes } trigger_event = { id = ywc_crisis.1410 } }
		if = { limit = { ywc_c05_mex_delivery_1416 = yes } trigger_event = { id = ywc_crisis.1410 } }
		if = { limit = { ywc_c05_nmg_delivery_1412 = yes } trigger_event = { id = ywc_crisis.1411 } }
	}
}
}
